function evidence = f90_xbatt07_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XBATT07_EXTRACT_REFERENCE_EVIDENCE Replay the exact current reference.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end

expectedModelPresence = ...
    "present";
expectedArchivePresence = ...
    "present";
expectedLicensePresence = ...
    "present";
assert(isfile(modelPath), "SimuVerity:F90:XBATT07:ModelMissing", ...
    "Reference model is missing: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XBATT07:OfficialScenarios", ...
    "Official scenarios are missing: %s", officialScenarios);
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XBATT07:ReferenceAssetRoot", ...
    "Evaluator-owned reference asset root is missing: %s", evaluatorAssetRoot);
declaredPresence = lower(strtrim(string("present")));
assert(declaredPresence == expectedModelPresence && ...
    localFilePresence(modelPath) == expectedModelPresence, ...
    "SimuVerity:F90:XBATT07:ReferenceIdentity", ...
    "Reference file presence differs from the exact task binding.");

archivePath = fullfile(evaluatorAssetRoot, "BatteryManagementSystem.mlproj");
licensePath = fullfile(evaluatorAssetRoot, "license.txt");
assetModelPath = fullfile(evaluatorAssetRoot, "XBATT07_reference_harness.slx");
assert(isfile(archivePath) && localFilePresence(archivePath) == expectedArchivePresence && ...
    isfile(licensePath) && localFilePresence(licensePath) == expectedLicensePresence && ...
    isfile(assetModelPath) && localFilePresence(assetModelPath) == expectedModelPresence, ...
    "SimuVerity:F90:XBATT07:ReferenceClosure", ...
    "The evaluator-owned XBATT-07 project closure is incomplete or changed.");
official = localOfficialScenarios(officialScenarios);

assert(~isfolder(outputDir), "SimuVerity:F90:XBATT07:OutputReuse", ...
    "Reference evidence output directory already exists: %s", outputDir);
mkdir(outputDir);
runtimeRoot = string(tempname);
mkdir(runtimeRoot);
runtimeCleanup = onCleanup(@() localRemoveTree(runtimeRoot)); %#ok<NASGU>
projectRoot = fullfile(runtimeRoot, "project");
harnessDir = fullfile(runtimeRoot, "harness");
cacheDir = fullfile(runtimeRoot, "cache");
codegenDir = fullfile(runtimeRoot, "codegen");
mkdir(harnessDir); mkdir(cacheDir); mkdir(codegenDir);
runtimeHarness = fullfile(harnessDir, "gate_BMS_Supervisor.slx");
copyfile(modelPath, runtimeHarness);
assert(localFilePresence(runtimeHarness) == expectedModelPresence, ...
    "SimuVerity:F90:XBATT07:RuntimeHarnessIdentity", ...
    "Evaluator-owned runtime copy differs from the current harness.");

oldPath = path;
oldFolder = string(pwd);
stateCleanup = onCleanup(@() localRestore(oldPath, oldFolder)); %#ok<NASGU>
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
scoringRunId = string(getenv("SIMUVERITY_SCORING_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XBATT07:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(strlength(scoringRunId) > 0, "SimuVerity:F90:XBATT07:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");

evidencePath = fullfile(outputDir, "evidence.json");
sourceModelPresenceBefore = localFilePresence(modelPath);
archivePresenceBefore = localFilePresence(archivePath);
licensePresenceBefore = localFilePresence(licensePath);
evidence = struct( ...
    "schema", "simuverity.f90-xbatt07-evidence.v1", ...
    "task_id", "F90-XBATT-07", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "reference_subject", true, ...
    "source_model", modelPath, ...
    "source_model_file_presence", sourceModelPresenceBefore, ...
    "reference_substantive_modifications", 0, ...
    "runtime_only_noninvasive_changes", true, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "golden_boundary", struct( ...
        "source_models", {{"State_Machine", "ContactorMgmt", ...
            "CurrPowerLimCalc", "FaultDetection"}}, ...
        "harness_role", "bus construction, source-model wiring, signal selection, and logging only", ...
        "golden_substantive_modifications", 0), ...
    "scenarios", struct([]), ...
    "all_scenarios_valid", false, ...
    "errors", struct, ...
    "model_closed_without_save", false, ...
    "project_closed_without_save", false, ...
    "reference_binding_preserved", false, ...
    "archive_binding_preserved", false, ...
    "license_binding_preserved", false, ...
    "runtime_copy_binding_preserved", false, ...
    "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "scoring_run_id", scoringRunId, ...
        "matlab_release", string(version("-release")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "temp", string(getenv("TEMP")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));
localWriteJson(evidencePath, evidence);

project = [];
model = "";
try
    matlab.project.extractProject(archivePath, projectRoot);
    project = matlab.project.loadProject(projectRoot);
    addpath(harnessDir, "-begin");
    cd(harnessDir);
    modelHandle = load_system(runtimeHarness);
    model = string(get_param(modelHandle, "Name"));
    assert(model == "gate_BMS_Supervisor", ...
        "SimuVerity:F90:XBATT07:ReferenceModelName", ...
        "Unexpected reference harness model name: %s", model);
    evidence.load_pass = true;
    set_param(model, ...
        "LimitDataPoints", "off", ...
        "StopTime", "25", ...
        "FixedStep", "0.1", ...
        "ReturnWorkspaceOutputs", "on");
    localConfigureScenario(model, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    localWriteJson(evidencePath, evidence);

    logNames = localLogNames;
    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).inputs = scenario;
        try
            localConfigureScenario(model, scenario);
            set_param(model, "SimulationCommand", "update");
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            logs = struct;
            for j = 1:numel(logNames)
                name = logNames{j};
                logs.(name) = localPackTimeseries(simOut.get(name), name);
            end
            rows(k).logs = logs;
            rows(k).valid = localValidateLogs(logs, logNames);
            clear simOut logs
        catch scenarioException
            rows(k).error_identifier = string(scenarioException.identifier);
            rows(k).error_message = string(scenarioException.message);
        end
        evidence.scenarios = rows;
        localWriteJson(evidencePath, evidence);
    end
    evidence.nominal_smoke_pass = rows(1).valid;
    evidence.all_scenarios_valid = all([rows.valid]);
    assert(evidence.all_scenarios_valid, "SimuVerity:F90:XBATT07:ScenarioEvidence", ...
        "One or more fixed reference scenarios did not produce valid evidence.");

    localCloseModel(model);
    evidence.model_closed_without_save = ~bdIsLoaded(model);
    model = "";
    evidence.project_closed_without_save = localCloseProject(project);
    project = [];
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourceModelPresenceBefore;
    evidence.archive_binding_preserved = localFilePresence(archivePath) == archivePresenceBefore;
    evidence.license_binding_preserved = localFilePresence(licensePath) == licensePresenceBefore;
    evidence.runtime_copy_binding_preserved = ...
        localFilePresence(runtimeHarness) == expectedModelPresence;
    evidence.EVIDENCE_COMPLETE = evidence.load_pass && ...
        evidence.update_pass && evidence.compile_pass && ...
        evidence.nominal_smoke_pass && evidence.all_scenarios_valid && ...
        evidence.model_closed_without_save && ...
        evidence.project_closed_without_save && ...
        evidence.reference_binding_preserved && ...
        evidence.archive_binding_preserved && ...
        evidence.license_binding_preserved && ...
        evidence.runtime_copy_binding_preserved;
    evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
    assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:F90:XBATT07:EvidenceIncomplete", ...
        "Reference extraction did not satisfy the evidence-lock prerequisites.");
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
catch sessionException
    try
        if strlength(model) > 0
            feval(model, [], [], [], "term");
        end
    catch
    end
    localCloseModel(model);
    evidence.model_closed_without_save = ...
        strlength(model) == 0 || ~bdIsLoaded(model);
    evidence.project_closed_without_save = localCloseProject(project);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourceModelPresenceBefore;
    evidence.archive_binding_preserved = localFilePresence(archivePath) == archivePresenceBefore;
    evidence.license_binding_preserved = localFilePresence(licensePath) == licensePresenceBefore;
    evidence.runtime_copy_binding_preserved = ...
        isfile(runtimeHarness) && localFilePresence(runtimeHarness) == expectedModelPresence;
    evidence.EVIDENCE_COMPLETE = false;
    evidence.evidence_complete = false;
    evidence.errors.session = localError(sessionException);
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
    rethrow(sessionException)
end

fprintf("F90_XBATT07_REFERENCE_EVIDENCE load=%d update=%d compile=%d valid=%d/%d complete=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    localValidCount(evidence.scenarios), numel(evidence.scenarios), ...
    evidence.EVIDENCE_COMPLETE, evidencePath);
end

function official = localOfficialScenarios(pathValue)
assert(localFilePresence(pathValue) == ...
    "present", ...
    "SimuVerity:F90:XBATT07:ScenarioIdentity", ...
    "Official scenario bytes differ from the current task contract.");
official = jsondecode(fileread(pathValue));
expectedIds = ["nominal_standby", "drive_precharge_ready", ...
    "drive_precharge_incomplete", "charge_precharge_ready", ...
    "voltage_temperature_derating", ...
    "overvoltage_overtemperature_fault"];
assert(isstruct(official) && string(official.schema) == ...
    "simuverity.official-scenarios.v1" && ...
    string(official.task_id) == "F90-XBATT-07" && ...
    isfield(official, "scenarios") && numel(official.scenarios) == 6 && ...
    isequal(string({official.scenarios.id}), expectedIds), ...
    "SimuVerity:F90:XBATT07:ScenarioContract", ...
    "Official scenario identity or ordering differs.");
end

function localConfigureScenario(model, scenario)
voltage = single(((scenario.cell_min_V + scenario.cell_max_V) / 2) * ones(96,1));
voltage(1) = single(scenario.cell_min_V);
voltage(2) = single(scenario.cell_max_V);
temperature = single(((scenario.cell_min_C + scenario.cell_max_C) / 2) * ones(96,1));
temperature(1) = single(scenario.cell_min_C);
temperature(2) = single(scenario.cell_max_C);
set_param(model + "/Cell_Voltages", "Value", ...
    "single(" + string(mat2str(double(voltage), 9)) + ")");
set_param(model + "/Cell_Temperatures", "Value", ...
    "single(" + string(mat2str(double(temperature), 9)) + ")");
set_param(model + "/Pack_Voltage", "Value", ...
    sprintf("single(%.9g)", scenario.pack_voltage_V));
set_param(model + "/Pack_Current", "Value", ...
    sprintf("single(%.9g)", scenario.pack_current_A));
set_param(model + "/Vout_Chgr", "Value", ...
    sprintf("single(%.9g)", scenario.charger_dc_voltage_V));
set_param(model + "/Vout_Invtr", "Value", ...
    sprintf("single(%.9g)", scenario.inverter_dc_voltage_V));
requests = {"SRE.Standby", "SRE.Charging", "SRE.Driving"};
requestIndex = double(scenario.state_request) + 1;
assert(requestIndex >= 1 && requestIndex <= numel(requests), ...
    "SimuVerity:F90:XBATT07:StateRequest", "Unsupported state request.");
set_param(model + "/StateRequest", "Value", requests{requestIndex});
end

function names = localLogNames
names = {'log_bms_state','log_charger_state','log_inverter_state', ...
    'log_cmd_PosCntctChgrCmd','log_cmd_PreChrgRelayChgrCmd','log_cmd_NegCntctChgrCmd', ...
    'log_cmd_PosCntctInvtrCmd','log_cmd_PreChrgRelayInvtrCmd','log_cmd_NegCntctInvtrCmd', ...
    'log_limit_DischargeCurrentLimit','log_limit_ChargeCurrentLimit', ...
    'log_extrema_MinCellVolt','log_extrema_MaxCellVolt', ...
    'log_extrema_MinCellTemp','log_extrema_MaxCellTemp', ...
    'log_critical_fault','log_limp_mode', ...
    'log_fault_PackOverCurrFlt','log_fault_CellHighTempFlt', ...
    'log_fault_CellLowTempFlt','log_fault_VoltSensorFlt', ...
    'log_fault_CellOverVoltFlt','log_fault_CellUnderVoltFlt', ...
    'log_fault_ChrgCntctFlt','log_fault_InvtrCntctFlt'};
end

function packed = localPackTimeseries(value, name)
assert(isa(value, "timeseries"), "SimuVerity:F90:XBATT07:OutputMissing", ...
    "Required native Timeseries %s is missing.", name);
time = double(value.Time(:));
data = localToDouble(value.Data);
packed = struct("time", time, "data", data);
end

function value = localToDouble(value)
try
    value = double(value);
catch
    value = arrayfun(@double, value);
end
value = squeeze(value);
if isrow(value) && numel(value) > 1, value = value(:); end
end

function valid = localValidateLogs(logs, names)
valid = true;
for k = 1:numel(names)
    value = logs.(names{k});
    valid = valid && ~isempty(value.time) && ...
        numel(value.time) == numel(value.data) && ...
        all(isfinite(value.time)) && all(isfinite(value.data(:))) && ...
        value.time(1) <= 1e-9 && value.time(end) >= 24.9;
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "valid", false, ...
    "simulation_wall_clock_s", NaN, ...
    "inputs", struct, ...
    "logs", struct, ...
    "error_identifier", "", ...
    "error_message", "");
end

function localCloseModel(model)
try
    if strlength(model) > 0 && bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function closed = localCloseProject(project)
closed = true;
try
    if ~isempty(project), close(project); end
catch
    closed = false;
end
end

function localRestore(oldPath, oldFolder)
try, cd(oldFolder); catch, end
try, path(oldPath); catch, end
end

function localRemoveTree(pathValue)
try
    if isfolder(pathValue), rmdir(pathValue, "s"); end
catch
end
end

function count = localValidCount(rows)
if isempty(rows) || ~isfield(rows, "valid")
    count = 0;
else
    count = sum([rows.valid]);
end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function info = localError(exception)
info = struct("identifier", string(exception.identifier), ...
    "message", string(exception.message), ...
    "report", string(getReport(exception, "extended", "hyperlinks", "off")));
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w");
assert(fid > 0, "SimuVerity:F90:XBATT07:JsonWrite", ...
    "Could not open JSON output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
